import{_ as t,o,c as a,a2 as r}from"./chunks/framework.YiAtXB4p.js";const p=JSON.parse('{"title":"Semantic Versioning","description":"","frontmatter":{"title":"Semantic Versioning","sourceFile":"guides/SEMVER.md"},"headers":[],"relativePath":"guide/semver.md","filePath":"guide/semver.md"}'),n={name:"guide/semver.md"};function d(i,e,s,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="semantic-versioning" tabindex="-1">Semantic Versioning <a class="header-anchor" href="#semantic-versioning" aria-label="Permalink to &quot;Semantic Versioning&quot;">​</a></h1><p><strong>Implements:</strong> <code>REL-01</code>, <code>REL-05</code>, <code>REL-06</code>, <code>GATE-03</code> · requirements stated in <a href="./charter">CHARTER.md</a> Part 8</p><p>How to decide whether a change to <code>@lgriffin/esi.ts</code> is a major, minor or patch release, and how to say so in a commit so the published version is right. <a href="./release">RELEASE.md</a> covers what happens after the commits land: release-please, the changelog, publishing and signing.</p><p>The version number is a promise to every consumer. <code>^9.9.0</code> in someone&#39;s <code>package.json</code> means &quot;install any 9.x.y release without my code breaking&quot;. A breaking change released as a minor breaks every one of those installs on their next <code>npm install</code>. A harmless change released as a major makes consumers read migration notes that do not exist. Both are bugs.</p><hr><h2 id="the-three-numbers" tabindex="-1">The three numbers <a class="header-anchor" href="#the-three-numbers" aria-label="Permalink to &quot;The three numbers&quot;">​</a></h2><p><code>MAJOR.MINOR.PATCH</code>, following <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning 2.0.0</a>.</p><table tabindex="0"><thead><tr><th>Bump</th><th>When</th><th>Commit</th></tr></thead><tbody><tr><td><strong>Major</strong></td><td>Code that compiled and ran against the previous release can fail against this one</td><td><code>type!:</code> subject and a <code>BREAKING CHANGE:</code> footer</td></tr><tr><td><strong>Minor</strong></td><td>New capability; everything that worked before still works the same way</td><td><code>feat:</code></td></tr><tr><td><strong>Patch</strong></td><td>A fix or internal change with no new capability and nothing removed</td><td><code>fix:</code>, <code>perf:</code>, <code>refactor:</code>, <code>chore:</code>, <code>docs:</code>, <code>test:</code></td></tr></tbody></table><p>The package is past 1.0, and release-please runs with <code>bump-minor-pre-major: false</code>, so these rules apply exactly as written. There is no &quot;it&#39;s only a minor break&quot;.</p><hr><h2 id="what-the-public-contract-is" tabindex="-1">What the public contract is <a class="header-anchor" href="#what-the-public-contract-is" aria-label="Permalink to &quot;What the public contract is&quot;">​</a></h2><p>Everything a consumer can reach without importing from <code>dist/</code> by path:</p><ul><li><strong>Every entry point in <code>package.json</code> <code>exports</code>:</strong> <code>.</code>, <code>./schemas</code>, <code>./errors</code>, <code>./testing</code>, <code>./client</code>, <code>./sde</code>, <code>./sde/memory</code>, and <code>./package.json</code>. <code>./testing</code> (<code>TestDataFactory</code> and friends) is public; consumers use it in their own tests.</li><li><strong>The types those entry points export.</strong> That includes interfaces consumers <em>implement</em>, such as <code>ILogger</code>, <code>ICircuitBreaker</code>, <code>IDeduplicator</code> and <code>IRetryStrategy</code>, as well as ones they only call.</li><li><strong>Runtime behaviour documented in the guides.</strong> This covers which error class is thrown and its <code>retryable</code> flag (<a href="./errors">ERRORS.md</a>), what a response schema accepts (<a href="./runtime-validation">RUNTIME-VALIDATION.md</a>), pagination results (<a href="./pagination">PAGINATION.md</a>), default configuration values, and log events other code may key on (<a href="./logging">LOGGING.md</a>).</li><li><strong>The environment.</strong> <code>engines.node</code>, the oldest supported TypeScript (5.4, checked by the consumer contract), <code>dependencies</code> whose types appear in the public API (<code>zod</code>), and <code>peerDependencies</code> (<code>better-sqlite3</code>, <code>js-yaml</code>, <code>adm-zip</code>), including their ranges.</li></ul><p>Not public: anything not reachable from an entry point, file layout under <code>src/</code>, test files, CI, generated files&#39; internal shape where no exported type depends on it, and log message wording.</p><hr><h2 id="deciding" tabindex="-1">Deciding <a class="header-anchor" href="#deciding" aria-label="Permalink to &quot;Deciding&quot;">​</a></h2><p>Ask: <strong>could code that works against the last release stop compiling, throw, or return something different?</strong> If yes, the change is major. The tables below cover the cases that come up in this repository.</p><h3 id="exports-and-signatures" tabindex="-1">Exports and signatures <a class="header-anchor" href="#exports-and-signatures" aria-label="Permalink to &quot;Exports and signatures&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Bump</th><th>Why</th></tr></thead><tbody><tr><td>Add an export, a client method, a sub-path export or an endpoint</td><td>minor</td><td>Nothing existing changes</td></tr><tr><td>Remove or rename an export, method, sub-path or endpoint</td><td>major</td><td>Importers stop compiling</td></tr><tr><td>Add an <strong>optional</strong> parameter or an optional config field</td><td>minor</td><td>Existing calls still type-check and behave the same</td></tr><tr><td>Add a <strong>required</strong> parameter, or make an optional one required</td><td>major</td><td>Existing calls stop compiling</td></tr><tr><td>Narrow a parameter type (<code>number | string</code> → <code>number</code>)</td><td>major</td><td>Callers passing the removed type stop compiling</td></tr><tr><td>Widen a parameter type (<code>number</code> → <code>number | string</code>)</td><td>minor</td><td>Existing calls still compile</td></tr><tr><td>Widen a return type (<code>T</code> → <code>T | undefined</code>)</td><td>major</td><td>Callers must handle a case they never saw</td></tr><tr><td>Narrow a return type (<code>T | undefined</code> → <code>T</code>)</td><td>minor</td><td>Existing handling still compiles</td></tr><tr><td>Add a <strong>required</strong> member to an interface consumers implement (<code>ILogger</code>)</td><td>major</td><td>Their implementations stop compiling. The API report shows only an added line, so the gate cannot catch this one</td></tr><tr><td>Add an <strong>optional</strong> member to such an interface</td><td>minor</td><td>Existing implementations still satisfy it</td></tr><tr><td>Add a required member to a type the library only returns</td><td>minor</td><td>Consumers read it; they never construct it</td></tr></tbody></table><h3 id="runtime-behaviour" tabindex="-1">Runtime behaviour <a class="header-anchor" href="#runtime-behaviour" aria-label="Permalink to &quot;Runtime behaviour&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Bump</th><th>Why</th></tr></thead><tbody><tr><td>Throw a different error class, or flip <code>retryable</code>, for an existing case</td><td>major</td><td><code>instanceof</code> checks and retry logic in consumer code change behaviour</td></tr><tr><td>Tighten a Zod response schema (a field becomes required, an enum loses a member)</td><td>major</td><td>Responses that validated before now throw <code>EsiValidationError</code> at runtime</td></tr><tr><td>Make a response field optional in a Zod schema</td><td>major</td><td>The inferred type widens to <code>T | undefined</code>, so consumer code that reads the field can stop compiling. This holds even when ESI already omits the field</td></tr><tr><td>Add a member to an ESI enum union in a response schema</td><td>minor</td><td>ESI enums are open by design (CHARTER principle 3): consumers must not switch on them exhaustively. <code>z.looseObject</code> keeps unknown fields regardless</td></tr><tr><td>Change a default that alters results: retry count, cache on or off, validation on or off, datasource</td><td>major</td><td>Same code, different outcome</td></tr><tr><td>Change a default that only alters timing or resource use, within documented bounds</td><td>patch</td><td>Results are the same</td></tr><tr><td>Fix a bug so the documented behaviour now happens</td><td>patch</td><td>The contract was already stated; the code now meets it</td></tr><tr><td>Fix a bug that consumers could reasonably depend on (an error that was swallowed now throws)</td><td>major, or patch with a changelog warning</td><td>Decide in the pull request and write the reason down; when unsure, ask the maintainer</td></tr><tr><td>Performance improvement with identical results</td><td>patch</td><td><code>perf:</code></td></tr></tbody></table><h3 id="environment-and-dependencies" tabindex="-1">Environment and dependencies <a class="header-anchor" href="#environment-and-dependencies" aria-label="Permalink to &quot;Environment and dependencies&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Bump</th><th>Why</th></tr></thead><tbody><tr><td>Drop a Node line (raise <code>engines.node</code>)</td><td>major</td><td>REL-05; installs on that line stop working</td></tr><tr><td>Raise the oldest supported TypeScript (<code>OLDEST_TYPESCRIPT</code>)</td><td>major</td><td>Consumers on that version stop compiling</td></tr><tr><td>Major version of a dependency whose types are public (<code>zod</code> 4 → 5)</td><td>major</td><td>Consumers&#39; schemas and inferred types change</td></tr><tr><td>Raise the minimum of a peer dependency (<code>better-sqlite3</code>)</td><td>major</td><td>Existing installs no longer satisfy it</td></tr><tr><td>Add a new required runtime dependency or peer dependency</td><td>major</td><td>Existing installs may break or warn</td></tr><tr><td>Patch or minor dependency update with no public type change</td><td>patch</td><td><code>chore(deps):</code></td></tr></tbody></table><h3 id="changes-that-come-from-esi-itself" tabindex="-1">Changes that come from ESI itself <a class="header-anchor" href="#changes-that-come-from-esi-itself" aria-label="Permalink to &quot;Changes that come from ESI itself&quot;">​</a></h3><p>CCP changes the ESI spec on its own schedule, and <code>npm run generate:types</code> follows. Classify the resulting library change by the tables above, not by what CCP called it:</p><ul><li><strong>ESI adds a field or an endpoint:</strong> minor.</li><li><strong>ESI removes an endpoint:</strong> deprecate it first (below). Removing the client method is a major release, even though the endpoint no longer works, because removal is what stops consumers&#39; code compiling.</li><li><strong>ESI stops always sending a field the schema requires:</strong> make it optional, as <code>fix(schemas)!:</code>. It fixes validation failures consumers already see, but the inferred type widens, so it is still a major release. Say both in the <code>BREAKING CHANGE:</code> footer.</li></ul><hr><h2 id="deprecate-before-you-remove" tabindex="-1">Deprecate before you remove <a class="header-anchor" href="#deprecate-before-you-remove" aria-label="Permalink to &quot;Deprecate before you remove&quot;">​</a></h2><p>A removal should never be the first a consumer hears of it.</p><ol><li><strong>In a minor release:</strong> mark the export <code>@deprecated</code> in JSDoc, naming the replacement. For an endpoint whose ESI operation is deprecated upstream, add <code>DeprecationInfo</code> (<code>message</code>, <code>replacedBy</code>, <code>sunsetDate</code>) to its definition, so <code>createClient</code> logs a warning on each call. A hand-written method logs through <code>logWarn(this._client, …)</code> (<a href="./design-rules">DESIGN-RULES.md</a> §3.6). Record it in the changelog under <strong>Deprecated</strong>.</li><li><strong>Keep it working</strong> for at least one minor release.</li><li><strong>In the next major release:</strong> remove it, with a <code>BREAKING CHANGE:</code> footer that names the replacement.</li></ol><p>When ESI has already removed the endpoint and every call fails, steps 1 and 3 can land in consecutive releases. The method still stays until a major release.</p><hr><h2 id="saying-it-in-the-commit" tabindex="-1">Saying it in the commit <a class="header-anchor" href="#saying-it-in-the-commit" aria-label="Permalink to &quot;Saying it in the commit&quot;">​</a></h2><p>release-please reads commit messages on <code>master</code> and nothing else. The only way to get the version right is to write the commit right. commitlint checks the format; it cannot check honesty.</p><h3 id="a-breaking-change" tabindex="-1">A breaking change <a class="header-anchor" href="#a-breaking-change" aria-label="Permalink to &quot;A breaking change&quot;">​</a></h3><p>Put <code>!</code> after the type <strong>and</strong> add a <code>BREAKING CHANGE:</code> footer that tells a consumer what to do:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat(market)!: require the order type in getMarketOrders</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fetching both sides of the book by default doubled the payload for the</span></span>
<span class="line"><span>common case of reading one side.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BREAKING CHANGE: getMarketOrders(regionId) is now</span></span>
<span class="line"><span>getMarketOrders(regionId, orderType), where orderType is &#39;buy&#39;, &#39;sell&#39; or</span></span>
<span class="line"><span>&#39;all&#39;. Pass &#39;all&#39; to keep the previous behaviour.</span></span></code></pre></div><p>The <code>!</code> triggers the major bump. The footer is the migration note that release-please copies into the changelog. Either one alone bumps the version, but a <code>!</code> without a footer ships a major release with no explanation.</p><h3 id="a-compatible-change-the-api-report-flags" tabindex="-1">A compatible change the API report flags <a class="header-anchor" href="#a-compatible-change-the-api-report-flags" aria-label="Permalink to &quot;A compatible change the API report flags&quot;">​</a></h3><p>Some compatible changes still remove or rewrite a line in <code>etc/esi.ts.api.md</code>, such as an optional parameter added to an existing signature. Say why it is compatible with an <code>API-Compatible:</code> trailer:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat(market): accept an optional type filter in getMarketOrders</span></span>
<span class="line"><span></span></span>
<span class="line"><span>API-Compatible: the new parameter is optional, so existing calls still type-check and return the same orders.</span></span></code></pre></div><h3 id="which-commit-carries-the-marker" tabindex="-1">Which commit carries the marker <a class="header-anchor" href="#which-commit-carries-the-marker" aria-label="Permalink to &quot;Which commit carries the marker&quot;">​</a></h3><ul><li>A pull request that contains the break carries the marker on the commit that introduces it.</li><li><strong>Never</strong> mark a change breaking &quot;to be safe&quot;. An unnecessary major release is also a wrong version.</li><li><strong>Never</strong> hide a break inside a <code>chore:</code>, <code>refactor:</code> or <code>test:</code> commit. The type describes the change to consumers, not the kind of work.</li></ul><hr><h2 id="merging-the-pull-request" tabindex="-1">Merging the pull request <a class="header-anchor" href="#merging-the-pull-request" aria-label="Permalink to &quot;Merging the pull request&quot;">​</a></h2><p>GitHub offers three ways to merge a pull request, and they give release-please different commits to read:</p><table tabindex="0"><thead><tr><th>Button</th><th>What lands on <code>master</code></th><th>What release-please reads</th></tr></thead><tbody><tr><td><strong>Merge commit</strong></td><td>Every commit from the branch, unchanged, plus one extra &quot;Merge pull request #N&quot; commit that joins the branch to <code>master</code></td><td>Each branch commit; the merge commit is ignored</td></tr><tr><td><strong>Squash and merge</strong></td><td>One new commit containing all the branch&#39;s changes. With several commits, its title is the <strong>pull request title</strong>; with one commit, it is that commit&#39;s message</td><td>That single commit</td></tr><tr><td><strong>Rebase and merge</strong></td><td>Every commit from the branch, replayed on top of <code>master</code>, with no merge commit</td><td>Each branch commit</td></tr></tbody></table><p>The consequences:</p><ul><li><strong>Merge commit or rebase:</strong> each commit&#39;s type and markers reach the changelog as written. Use one of these when a pull request mixes types, for example a <code>fix:</code> alongside <code>test:</code> commits, so each gets its own changelog entry.</li><li><strong>Squash:</strong> the pull request title becomes the only commit title. It <strong>must</strong> be a conventional commit, and it must carry <code>!</code> when any commit in the pull request is breaking. Write any <code>BREAKING CHANGE:</code> footer into the squash dialog&#39;s message box too. Squash also collapses the changelog to one entry.</li></ul><hr><h2 id="what-checks-it" tabindex="-1">What checks it <a class="header-anchor" href="#what-checks-it" aria-label="Permalink to &quot;What checks it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>What it catches</th><th>Where</th></tr></thead><tbody><tr><td>commitlint</td><td>A commit message that is not a conventional commit</td><td><code>commit-msg</code> hook</td></tr><tr><td>API surface diff (GATE-03)</td><td>An exported shape changed without <code>etc/esi.ts.api.md</code> being regenerated (<code>npm run api-report</code>)</td><td><code>ci.yml</code> API Surface Check</td></tr><tr><td><code>publicApiSurface.test.ts</code></td><td>A root export renamed or removed</td><td><code>npm test</code></td></tr><tr><td><code>api-semver</code> gate (REL-06), added by <a href="https://github.com/lgriffin/ESI.ts/pull/310" target="_blank" rel="noreferrer">#310</a></td><td>The API report lost or changed a line, but no commit is <code>type!:</code>, has a <code>BREAKING CHANGE:</code> footer or an <code>API-Compatible:</code> trailer; or a declared break spans several commits and the pull request title is not <code>type!:</code></td><td><code>ci.yml</code>, <code>npm run api-report:semver</code></td></tr><tr><td>Review</td><td>Everything else in <a href="#deciding">Deciding</a>: runtime behaviour, schema tightening, defaults, required members on implemented interfaces, sub-paths the report does not cover, dependency changes</td><td><a href="https://github.com/lgriffin/ESI.ts/blob/master/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a> Reviewer Checklist</td></tr></tbody></table><p>The API report covers only the root entry point, and it cannot see runtime behaviour. The gate is a tripwire for the common case, not a proof. The author is responsible for the classification, and the reviewer checks it.</p><hr><h2 id="checklist-for-every-pull-request" tabindex="-1">Checklist for every pull request <a class="header-anchor" href="#checklist-for-every-pull-request" aria-label="Permalink to &quot;Checklist for every pull request&quot;">​</a></h2><ol><li>Does the change touch anything in <a href="#what-the-public-contract-is">the public contract</a>? If not, it is a patch-level type (<code>fix:</code>, <code>refactor:</code>, <code>chore:</code> and so on) and you are done.</li><li>Classify it with the tables in <a href="#deciding">Deciding</a>.</li><li>If an exported shape changed, run <code>npm run api-report</code> and commit <code>etc/esi.ts.api.md</code>.</li><li>Breaking: <code>type!:</code> plus a <code>BREAKING CHANGE:</code> footer with the migration. If it removes something, was it deprecated in an earlier minor release? If not, deprecate first unless ESI has already removed it.</li><li>Compatible but flagged by the report: an <code>API-Compatible:</code> trailer with the reason.</li><li>Squash-merging several commits: pull request title in conventional form, with <code>!</code> if anything is breaking.</li></ol>`,56)])])}const g=t(n,[["render",d]]);export{p as __pageData,g as default};
